@startuml

class Customer {
  + name : string
  + surname : string
  + email : string
  + telephone : string
  + homeAddress : string
}

class Order {
  + totalCost : double
  + estimatedDeliveryTime : time
  + status : string
}

class Dish {
  + name : string
}

class Payment {
  + creditCardInfo : string
  + isSuccessful : boolean
}

class Kitchen {
  + currentWorkload : int
}

class DeliveryStaff {
  + reportCompletion() : void
}

Customer "1" -- "*" Order : places
Order "*" -- "1..*" Dish : contains
Order "1" -- "1" Payment : processed by
Order "*" -- "1" Kitchen : sent to
Order "1" -- "1" DeliveryStaff : delivered by

@enduml

